const path = require("node:path");
const {
  createContractProgram,
  renderTypeAliases,
  writeOrCheckContract,
  checkContractDeclarations,
} = require("./contract-generation.cjs");

const source = path.resolve(__dirname, "../src/lib/order-finance/contracts.ts");
const target = path.resolve(__dirname, "../.mercur/finance-contracts.d.ts");
const program = createContractProgram([source], { skipLibCheck: false });
const result =
  "// Generated by scripts/generate-finance-contracts.cjs. Do not edit.\n" +
  renderTypeAliases(program, [source]) +
  "\n";

if (
  writeOrCheckContract(
    target,
    result,
    "Finance contracts are stale; run pnpm finance:contracts:generate",
  )
) {
  checkContractDeclarations(
    [target, path.resolve(__dirname, "finance-contracts-consumer-check.ts")],
    "Finance contract declaration or consumer failed typechecking",
  );
}
